import java.io.*;
import java.util.StringTokenizer;

public class Main {
    static long countLeq(long[] a, long limit) {
        int n = a.length;
        int r = 0;            // 窗口 [l, r)
        long windowSum = 0;   // 窗口内处理时间之和
        long curCost = 0;     // 当前窗口的加权成本
        long cnt = 0;

        for (int l = 0; l < n; l++) {
            // 右扩
            while (r < n) {
                long newSum = windowSum + a[r];
                long newCost = curCost + newSum;
                if (newCost > limit) {
                    break;
                }
                windowSum = newSum;
                curCost = newCost;
                r++;
            }

            cnt += r - l;

            // 左缩
            if (r > l) {
                curCost -= (long) (r - l) * a[l];
                windowSum -= a[l];
            } else {
                r = l + 1;
            }
        }
        return cnt;
    }

    static long kthSmallestCost(long[] a, long k) {
        int n = a.length;
        // 上界：整个区间的加权成本
        long running = 0;
        long high = 0;
        for (long x : a) {
            running += x;
            high += running;
        }

        long low = 0;
        while (low < high) {
            long mid = low + (high - low) / 2;
            if (countLeq(a, mid) >= k) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        int t = Integer.parseInt(br.readLine());

        while (t-- > 0) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int n = Integer.parseInt(st.nextToken());
            long k = Long.parseLong(st.nextToken());
            long[] a = new long[n];
            st = new StringTokenizer(br.readLine());
            for (int i = 0; i < n; i++) {
                a[i] = Long.parseLong(st.nextToken());
            }
            sb.append(kthSmallestCost(a, k)).append('\n');
        }
        System.out.print(sb);
    }
}
